import java.io.InputStreamReader;
import static org.junit.Assert.*;
import static com.github.davidmoten.guavamini.Preconditions.checkArgument;

public class WordWrapTest {

    @Test
    public void fromReaderTest() {
        String text = "Hello World";
        String resource = new String(text.getBytes(), StandardCharsets.UTF_8);
        WordWrap.Builder builder = WordWrap.fromUtf8(new ByteArrayInputStream(resource.getBytes()));
        Preconditions.assertState(builder, WordWrap.class, true);
    }

    @Test
    public void fromReaderCloseTest() {
        String text = "Hello World";
        String resource = new String(text.getBytes(), StandardCharsets.UTF_8);
        WordWrap.Builder builder = WordWrap.fromUtf8(new ByteArrayInputStream(resource.getBytes()));
        WordWrap.close(builder.reader());
    }

    @Test
    public void fromClasspathResourceTest() {
        String text = "Hello World";
        WordWrap.Builder builder = WordWrap.fromClasspathUtf8("hello");
        Preconditions.assertState(builder, WordWrap.class, true);
    }

    @Test
    public void fromClasspathResourceCloseTest() {
        String text = "Hello World";
        WordWrap.Builder builder = WordWrap.fromClasspathUtf8("hello");
        WordWrap.close(builder.reader());
    }

    @Test
    public void fromCharSequenceTest() {
        String text = "Hello World";
        WordWrap.Builder builder = WordWrap.from(text);
        Preconditions.assertState(builder, WordWrap.class, true);
    }

    @Test
    public void wordWrapReaderWriterTest() throws IOException {
        String text = "Hello World";
        WordWrap.Builder builder = WordWrap.fromUtf8(new ByteArrayInputStream(text.getBytes()));
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writer(out::writeBytes, 80);
        WordWrap.wordWrap(builder.reader(), out, "\n", 80, (s) -> s.length(), new HashSet<>(), false, true);
        assertTrue(out.toString().contains("Hello\nWorld"));
    }

    @Test
    public void wordWrapReaderLineConsumerTest() throws IOException {
        String text = "Hello World";
        WordWrap.Builder builder = WordWrap.fromUtf8(new ByteArrayInputStream(text.getBytes()));
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writer(out::writeBytes, 80);
        WordWrap.wordWrap(builder.reader(), out, "\n", 80, (s) -> s.length(), new HashSet<>(), false, true);
        assertTrue(out.toString().contains("Hello\nWorld"));
    }

    @Test
    public void isWhitespaceCharSequenceTest() {
        char[] chars = {'\t', ' ', '\r'};
        for (char c : chars) {
            assertTrue(WordWrap.isWhitespace(new StringBuilder(String.valueOf(c))));
            assertFalse(WordWrap.isWhitespace(new StringBuilder(String.valueOf('!'))));
        }
    }

    @Test
    public void rightTrimCharSequenceTest() {
        String s = "   Hello World  ";
        Preconditions.assertState(WordWrap.rightTrim(s), String.class, !s.equals(WordWrap.rightTrim(s)));
    }

    private static final class writer implements LineConsumer {
        private final ByteArrayOutputStream out;

        public writer(Consumer<ByteString> action) {
            this.out = new ByteArrayOutputStream();
        }

        @Override
        public void writeLine(String s) throws IOException {
            out.writeBytes("\n".getBytes());
            action.accept(new ByteString(s));
        }
    }

    private static class ByteString implements CharSequence {
        private final String str;

        public ByteString(String str) {
            this.str = str;
        }

        @Override
        public int length() {
            return str.length();
        }

        @Override
        public char at(int i) {
            return str.charAt(i);
        }

        @Override
        public CharSequence subSequence(int start, int end) {
            return str.subSequence(start, end);
        }
    }

